const KM_VOICE_FILES = {"CaiDat_Mac.command": "#!/bin/bash\ncd \"$(dirname \"$0\")\"\necho \"==== CÀI ĐẶT TDK GIỌNG (VieNeu-TTS) ====\"\nPY=$(command -v python3 || true)\nif [ -z \"$PY\" ] || ! \"$PY\" -c 'import sys; sys.exit(0 if sys.version_info>=(3,10) else 1)'; then\n  echo \"Cần Python 3.10 trở lên — trình duyệt sẽ mở trang tải Python.\"; open \"https://www.python.org/downloads/macos/\"; read -p \"Nhấn Enter để thoát…\"; exit 1\nfi\n[ -d .venv ] || \"$PY\" -m venv .venv || { echo \"Không tạo được môi trường Python\"; read -p \"Enter…\"; exit 1; }\n.venv/bin/python -m pip install --upgrade pip\n.venv/bin/python -m pip install --upgrade vieneu || { echo \"Cài VieNeu lỗi — kiểm tra mạng rồi chạy lại\"; read -p \"Enter…\"; exit 1; }\necho \"==== XONG! Bấm đúp ChayGiong_Mac.command để bật trạm giọng. ====\"\nread -p \"Nhấn Enter để đóng…\"\n", "CaiDat_Windows.bat": "@echo off\r\nchcp 65001 >nul\r\ncd /d \"%~dp0\"\r\ntitle Cai dat TDK Giong\r\necho ==== CAI DAT TDK GIONG (VieNeu-TTS) ====\r\nset \"PY=\"\r\nwhere py >nul 2>nul && set \"PY=py -3\"\r\nif not defined PY (where python >nul 2>nul && set \"PY=python\")\r\nif not defined PY (\r\n  echo Chua co Python. Trinh duyet se mo trang tai Python 3.11 - khi cai NHO TICH \"Add python.exe to PATH\".\r\n  start https://www.python.org/downloads/windows/\r\n  pause\r\n  exit /b 1\r\n)\r\n%PY% -c \"import sys; sys.exit(0 if sys.version_info>=(3,10) else 1)\" || (echo Can Python 3.10 tro len. & start https://www.python.org/downloads/windows/ & pause & exit /b 1)\r\nif not exist .venv (%PY% -m venv .venv || (echo Khong tao duoc moi truong Python. & pause & exit /b 1))\r\n.venv\\Scripts\\python -m pip install --upgrade pip\r\n.venv\\Scripts\\python -m pip install --upgrade vieneu || (echo Cai VieNeu loi - kiem tra mang roi chay lai. & pause & exit /b 1)\r\necho.\r\necho ==== XONG! Bay gio bam dup ChayGiong_Windows.bat de bat tram giong. ====\r\npause\r\n", "ChayGiong_Mac.command": "#!/bin/bash\ncd \"$(dirname \"$0\")\"\n[ -x .venv/bin/python ] || { echo \"Chưa cài đặt — bấm đúp CaiDat_Mac.command trước.\"; read -p \"Enter…\"; exit 1; }\n.venv/bin/python tdk_giong.py\n", "ChayGiong_Windows.bat": "@echo off\r\nchcp 65001 >nul\r\ncd /d \"%~dp0\"\r\ntitle TDK Giong - giu cua so nay mo\r\nif not exist .venv\\Scripts\\python.exe (echo Chua cai dat. Hay bam dup CaiDat_Windows.bat truoc. & pause & exit /b 1)\r\nset PYTHONIOENCODING=utf-8\r\n.venv\\Scripts\\python tdk_giong.py\r\npause\r\n", "HUONG_DAN.txt": "TDK GIỌNG — giọng đọc AI tiếng Việt chạy trên máy, miễn phí, không giới hạn\n(dùng mô hình mã nguồn mở VieNeu-TTS, giấy phép Apache 2.0 — https://github.com/pnnbao97/VieNeu-TTS)\n\n1. CÀI ĐẶT (làm 1 lần)\n   - Windows: bấm đúp CaiDat_Windows.bat\n     (nếu máy chưa có Python, trang tải sẽ tự mở — cài Python 3.11, NHỚ TÍCH \"Add python.exe to PATH\", rồi bấm lại CaiDat)\n   - Mac: chuột phải CaiDat_Mac.command → Open\n   Cần mạng Internet; lần cài đầu mất vài phút.\n\n2. MỖI LẦN LÀM VIDEO\n   - Windows: bấm đúp ChayGiong_Windows.bat — Mac: chuột phải ChayGiong_Mac.command → Open\n   - Lần chạy đầu sẽ tải mô hình (vài trăm MB). Khi thấy dòng \"✅ TDK Giọng đã sẵn sàng\" là dùng được.\n   - GIỮ CỬA SỔ ĐEN NÀY MỞ trong lúc làm video.\n   - Trên web: Tạo video → Giọng đọc → Nguồn giọng: \"Giọng trên máy\". Nếu trình duyệt hỏi\n     \"cho phép trang truy cập thiết bị trong mạng cục bộ\" → bấm CHO PHÉP.\n\n3. TẠO GIỌNG CỦA TÔI (nhân bản giọng)\n   Trong web bấm \"Tạo giọng của tôi\", đọc 3 câu ngắn (khoảng 8 giây tổng). Web lọc ồn, làm ấm giọng rồi gửi cho trạm.\n   Chỉ nhân bản giọng của chính mình hoặc người đã đồng ý.\n\nGiọng đã tạo nằm trong thư mục giong_cua_toi (mỗi giọng là một tệp .wav) — có thể sao lưu sang máy khác.\nMáy yếu: đặt biến môi trường TDK_GIONG_CHE_DO=v3nano để dùng bản nhẹ (nhanh hơn, giọng kém hơn, không nhân bản giọng).\n", "tdk_giong.py": "# -*- coding: utf-8 -*-\n\"\"\"TDK Giọng — trạm giọng đọc AI tiếng Việt chạy trên máy (dùng VieNeu-TTS, giấy phép Apache 2.0).\nWeb chuanhoacodeTDK (tab Tạo video) gọi trạm này để lồng tiếng từng câu, khớp chữ trong video.\nTác giả web: ThS. Trương Đăng Khoa.\nVieNeu-TTS © Phạm Nguyễn Ngọc Bảo — https://github.com/pnnbao97/VieNeu-TTS (Apache License 2.0).\"\"\"\nimport base64, io, json, os, re, sys, tempfile, threading, time, wave\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom urllib.parse import urlparse\n\nPHIEN_BAN = \"1.1\"\nCONG = int(os.environ.get(\"TDK_GIONG_CONG\", \"8765\"))\nTHU_MUC = os.path.dirname(os.path.abspath(__file__))\nTHU_MUC_GIONG = os.path.join(THU_MUC, \"giong_cua_toi\")\nos.makedirs(THU_MUC_GIONG, exist_ok=True)\n\n# Các trang được phép gọi trạm (thêm tên miền khác vào tệp nguon_cho_phep.txt, mỗi dòng một tên miền)\nNGUON_MAC_DINH = [r\"^https://(www\\.)?kmath\\.io\\.vn$\", r\"^https://[\\w.-]+\\.github\\.io$\", r\"^https?://(localhost|127\\.0\\.0\\.1)(:\\d+)?$\", r\"^null$\"]\ndef nguon_cho_phep():\n    ds = list(NGUON_MAC_DINH)\n    p = os.path.join(THU_MUC, \"nguon_cho_phep.txt\")\n    if os.path.exists(p):\n        for d in open(p, encoding=\"utf-8\"):\n            d = d.strip()\n            if d and not d.startswith(\"#\"):\n                ds.append(\"^\" + re.escape(d.rstrip(\"/\")) + \"$\")\n    return ds\n\ndef in_ra(*a):\n    print(time.strftime(\"[%H:%M:%S]\"), *a, flush=True)\n\nin_ra(\"Đang nạp mô hình giọng đọc VieNeu-TTS (lần đầu sẽ tải mô hình, vui lòng chờ)…\")\ntry:\n    from vieneu import Vieneu\nexcept ImportError:\n    in_ra(\"CHƯA CÀI VieNeu. Hãy chạy tệp CaiDat trước.\")\n    input(\"Nhấn Enter để thoát…\"); sys.exit(1)\n\nCHE_DO = os.environ.get(\"TDK_GIONG_CHE_DO\", \"\")  # \"\" = Turbo (mặc định), \"v3nano\" = nhẹ nhất\ntry:\n    tts = Vieneu(mode=CHE_DO) if CHE_DO else Vieneu()\nexcept Exception as e:\n    in_ra(\"Không nạp được mô hình:\", e); input(\"Nhấn Enter để thoát…\"); sys.exit(1)\nkhoa = threading.Lock()\n\ndef ds_giong_mau():\n    try:\n        return [{\"ten\": str(nhan), \"id\": str(vid)} for nhan, vid in tts.list_preset_voices()]\n    except Exception:\n        return []\n\ndef ds_giong_toi():\n    return sorted(os.path.splitext(f)[0] for f in os.listdir(THU_MUC_GIONG) if f.lower().endswith(\".wav\"))\n\ndef nap_giong_toi():\n    for ten in ds_giong_toi():\n        try:\n            tts.add_voice(ten, os.path.join(THU_MUC_GIONG, ten + \".wav\"))\n        except Exception as e:\n            in_ra(\"Không nạp được giọng\", ten, \":\", e)\nnap_giong_toi()\n\ndef cac_ten(voice):\n    \"\"\"Thử lần lượt: đúng tên gửi lên, rồi tên/ mã tương ứng của giọng mẫu.\"\"\"\n    ds = [voice]\n    for g in ds_giong_mau():\n        if voice in (g[\"ten\"], g[\"id\"]):\n            ds += [g[\"ten\"], g[\"id\"]]\n    return [v for i, v in enumerate(ds) if v and v not in ds[:i]]\n\ndef doc(text, voice):\n    with khoa:\n        audio, loi = None, None\n        for v in (cac_ten(voice) if voice else [None]):\n            try:\n                audio = tts.infer(text, voice=v) if v else tts.infer(text)\n                break\n            except Exception as e:\n                loi = e\n        if audio is None:\n            raise loi or RuntimeError(\"không đọc được\")\n        fd, p = tempfile.mkstemp(suffix=\".wav\"); os.close(fd)\n        try:\n            tts.save(audio, p)\n            with open(p, \"rb\") as f:\n                return f.read()\n        finally:\n            try: os.remove(p)\n            except OSError: pass\n\ndef ten_an_toan(t):\n    t = re.sub(r\"[\\\\/:*?\\\"<>|\\r\\n\\t]\", \"\", (t or \"\").strip())[:40]\n    return t or \"Giọng của tôi\"\n\nclass XuLy(BaseHTTPRequestHandler):\n    server_version = \"TDKGiong/\" + PHIEN_BAN\n    def log_message(self, *a):\n        pass\n    def _cors(self):\n        o = self.headers.get(\"Origin\", \"\")\n        if o and any(re.match(r, o) for r in nguon_cho_phep()):\n            self.send_header(\"Access-Control-Allow-Origin\", o)\n            self.send_header(\"Vary\", \"Origin\")\n        self.send_header(\"Access-Control-Allow-Methods\", \"GET, POST, OPTIONS\")\n        self.send_header(\"Access-Control-Allow-Headers\", \"Content-Type\")\n        self.send_header(\"Access-Control-Allow-Private-Network\", \"true\")\n        self.send_header(\"Access-Control-Expose-Headers\", \"X-Ten-Giong\")\n    def _json(self, ma, obj):\n        b = json.dumps(obj, ensure_ascii=False).encode(\"utf-8\")\n        self.send_response(ma); self._cors()\n        self.send_header(\"Content-Type\", \"application/json; charset=utf-8\"); self.send_header(\"Content-Length\", str(len(b))); self.end_headers(); self.wfile.write(b)\n    def _doc_json(self):\n        n = int(self.headers.get(\"Content-Length\", \"0\") or 0)\n        if n > 30 * 1024 * 1024: raise ValueError(\"dữ liệu quá lớn\")\n        return json.loads(self.rfile.read(n).decode(\"utf-8\") or \"{}\")\n    def _nguon_hop_le(self):\n        o = self.headers.get(\"Origin\", \"\")\n        return (not o) or any(re.match(r, o) for r in nguon_cho_phep())\n    def do_OPTIONS(self):\n        self.send_response(204); self._cors(); self.end_headers()\n    def do_GET(self):\n        if not self._nguon_hop_le(): return self._json(403, {\"loi\": \"trang này không được phép dùng trạm giọng\"})\n        if urlparse(self.path).path in (\"/\", \"/health\"):\n            return self._json(200, {\"ok\": True, \"ten\": \"TDK Giọng\", \"phienBan\": PHIEN_BAN, \"cheDo\": CHE_DO or \"v3-turbo\", \"giongMau\": ds_giong_mau(), \"giongToi\": ds_giong_toi()})\n        self._json(404, {\"loi\": \"không có đường dẫn này\"})\n    def do_POST(self):\n        if not self._nguon_hop_le(): return self._json(403, {\"loi\": \"trang này không được phép dùng trạm giọng\"})\n        duong = urlparse(self.path).path\n        try:\n            d = self._doc_json()\n            if duong == \"/tts\":\n                text = (d.get(\"text\") or \"\").strip()\n                if not text: return self._json(400, {\"loi\": \"thiếu câu cần đọc\"})\n                t0 = time.time(); wav = doc(text[:2000], d.get(\"voice\") or \"\")\n                in_ra(\"Đã đọc %d ký tự trong %.1fs\" % (len(text), time.time() - t0))\n                self.send_response(200); self._cors(); self.send_header(\"Content-Type\", \"audio/wav\"); self.send_header(\"Content-Length\", str(len(wav))); self.end_headers(); self.wfile.write(wav); return\n            if duong == \"/clone\":\n                ten = ten_an_toan(d.get(\"ten\")); du_lieu = base64.b64decode(d.get(\"wav\") or \"\")\n                if len(du_lieu) < 2000: return self._json(400, {\"loi\": \"đoạn ghi âm quá ngắn\"})\n                p = os.path.join(THU_MUC_GIONG, ten + \".wav\")\n                with open(p, \"wb\") as f: f.write(du_lieu)\n                if d.get(\"denoise\", True):\n                    try:\n                        p2 = p[:-4] + \"_sach.wav\"\n                        with khoa: tts.denoise(p, out_path=p2)\n                        if os.path.exists(p2) and os.path.getsize(p2) > 2000: os.replace(p2, p)\n                    except Exception as e: in_ra(\"Bỏ qua bước lọc ồn:\", e)\n                with khoa: tts.add_voice(ten, p)\n                in_ra(\"Đã tạo giọng:\", ten)\n                return self._json(200, {\"ok\": True, \"ten\": ten, \"giongToi\": ds_giong_toi()})\n            if duong == \"/xoa\":\n                ten = ten_an_toan(d.get(\"ten\")); p = os.path.join(THU_MUC_GIONG, ten + \".wav\")\n                if os.path.exists(p): os.remove(p)\n                return self._json(200, {\"ok\": True, \"giongToi\": ds_giong_toi()})\n            self._json(404, {\"loi\": \"không có đường dẫn này\"})\n        except Exception as e:\n            in_ra(\"Lỗi:\", e); self._json(500, {\"loi\": str(e)})\n\nif __name__ == \"__main__\":\n    try:\n        may = ThreadingHTTPServer((\"127.0.0.1\", CONG), XuLy)\n    except OSError:\n        in_ra(\"Cổng %d đang bận — có thể trạm giọng đã chạy ở cửa sổ khác.\" % CONG); input(\"Nhấn Enter để thoát…\"); sys.exit(1)\n    in_ra(\"✅ TDK Giọng đã sẵn sàng tại http://127.0.0.1:%d — giữ cửa sổ này mở trong lúc làm video.\" % CONG)\n    in_ra(\"Giọng có sẵn:\", \", \".join(g[\"ten\"] for g in ds_giong_mau()) or \"(không đọc được danh sách)\")\n    in_ra(\"Giọng của tôi:\", \", \".join(ds_giong_toi()) or \"(chưa có — tạo trong web: Tạo video → Giọng đọc → Giọng trên máy)\")\n    try:\n        may.serve_forever()\n    except KeyboardInterrupt:\n        pass\n"};
